USE aerosoft360_rebuild;
CREATE TABLE IF NOT EXISTS attendance_imports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_name VARCHAR(255) NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,record_count INT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'validated',warnings JSON NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attendance_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attendance_import_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,attendance_status VARCHAR(30) NOT NULL,paid_days DECIMAL(5,2) NOT NULL DEFAULT 0,no_pay_days DECIMAL(5,2) NOT NULL DEFAULT 0,overtime_hours DECIMAL(8,2) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY attendance_record_unique(attendance_import_id,employee_id,attendance_date),FOREIGN KEY(attendance_import_id) REFERENCES attendance_imports(id) ON DELETE CASCADE,FOREIGN KEY(employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
ALTER TABLE payroll_runs ADD COLUMN IF NOT EXISTS attendance_import_id BIGINT UNSIGNED NULL AFTER id;
ALTER TABLE payroll_items ADD COLUMN IF NOT EXISTS paid_days DECIMAL(6,2) NOT NULL DEFAULT 0 AFTER employee_id, ADD COLUMN IF NOT EXISTS no_pay_days DECIMAL(6,2) NOT NULL DEFAULT 0 AFTER paid_days, ADD COLUMN IF NOT EXISTS no_pay_amount DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER no_pay_days, ADD COLUMN IF NOT EXISTS overtime_hours DECIMAL(8,2) NOT NULL DEFAULT 0 AFTER no_pay_amount;
